    {
      "fullUrl": "https://example.org/fhir/Observation/observation-1",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-1",
        "status": "final",
        "code": {
          "text": "Right upper eyelid lump"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Patient reports a focal lump at the right upper eyelid margin, like a little pea, present for a week or two, possibly longer; onset is uncertain.",
        "note": [
          {
            "text": "Telephone history only; no visual examination."
          }
        ]
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-2",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-2",
        "status": "final",
        "code": {
          "text": "Eyelid discomfort and functional effect"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Lump feels annoying/heavy rather than painful, is not really sore, and is in the way when reading or watching television."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-3",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-3",
        "status": "final",
        "code": {
          "text": "Eyelid lump consistency and tenderness"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Patient reports the lump feels firm but not rock hard and is not very tender when pressed. Clinician's description-based assessment characterizes it as non-tender.",
        "note": [
          {
            "text": "Not directly examined."
          }
        ]
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-4",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-4",
        "status": "final",
        "code": {
          "text": "Morning eye crusting"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Eyes are often a bit crusty in the mornings; usual morning crusting without increased discharge."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-5",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-5",
        "status": "final",
        "code": {
          "text": "Vision and diplopia"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Patient reports vision is okay and denies diplopia.",
        "note": [
          {
            "text": "Telephone history only."
          }
        ]
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-6",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-6",
        "status": "final",
        "code": {
          "text": "Eye pain and pain with eye movements"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "No significant eye pain and no painful extraocular movements reported."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-7",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-7",
        "status": "final",
        "code": {
          "text": "Photophobia"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Denied."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-8",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-8",
        "status": "final",
        "code": {
          "text": "Eye discharge"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "No increased discharge, only usual morning crusting. Description-based examination summary records no discharge.",
        "note": [
          {
            "text": "Telephone assessment only."
          }
        ]
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-9",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-9",
        "status": "final",
        "code": {
          "text": "Fever and systemic symptoms"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "No fever, no feeling systemically unwell and no systemic symptoms reported."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-10",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-10",
        "status": "final",
        "code": {
          "text": "Eyelid erythema, swelling and spread"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "No diffuse eyelid erythema or diffuse swelling; described as just a bump. No spread to the cheek or forehead.",
        "note": [
          {
            "text": "Based on telephone history and patient description, not visual examination."
          }
        ]
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-11",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-11",
        "status": "final",
        "code": {
          "text": "Ability to open and close the eye"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Patient reports being able to open and close the eye fully."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-12",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-12",
        "status": "final",
        "code": {
          "text": "History of similar eyelid lesion"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Patient reports a similar lesion years ago that settled with hot flannels, possibly also an antibiotic cream; treatment history is uncertain."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-13",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-13",
        "status": "final",
        "code": {
          "text": "Patient attribution of eyelid lump"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Patient thinks the lump may be related to an old pillow or too much television; this is the patient's speculation, not an established cause."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-14",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-14",
        "status": "final",
        "code": {
          "text": "Reliability of history and recall"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Clinician assesses patient as a poor historian with poor recall; onset and treatment timeline are unreliable. Patient cannot clearly identify medication over the phone."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-15",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-15",
        "status": "final",
        "code": {
          "text": "Knee symptoms"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Patient reports her knees have been worse again; further symptom details were not obtained."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-16",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-16",
        "status": "final",
        "code": {
          "text": "Homebound status"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Homebound."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-17",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-17",
        "status": "final",
        "code": {
          "text": "Anticoagulant use documented in past notes"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Past notes document no anticoagulant use; current medications are unclear over the phone."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-18",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-18",
        "status": "final",
        "code": {
          "text": "Diabetes documentation"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "No diabetes mellitus on record."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/MedicationStatement/medication-statement-1",
      "resource": {
        "resourceType": "MedicationStatement",
        "id": "medication-statement-1",
        "status": "active",
        "medicationCodeableConcept": {
          "text": "Unidentified pill for blood pressure"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "note": [
          {
            "text": "Patient describes a little white pill, or possibly blue, for her pressure. Medication identity, dose and frequency are unclear over the phone and require confirmation."
          }
        ]
      }
    },
    {
      "fullUrl": "https://example.org/fhir/MedicationStatement/medication-statement-2",
      "resource": {
        "resourceType": "MedicationStatement",
        "id": "medication-statement-2",
        "status": "unknown",
        "medicationCodeableConcept": {
          "text": "Unidentified antibiotic cream"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "effectiveString": "Possibly used years ago for a similar eyelid lesion",
        "note": [
          {
            "text": "Patient is unsure whether an antibiotic cream was used alongside hot flannels. Historical use is uncertain; no drug name, dose, frequency or course duration is available."
          }
        ]
      }
    }
  ]
}

